import{_ as t,o as h,c as i,a2 as c}from"./chunks/framework.O93z6AWZ.js";const e=JSON.parse('{"title":"PHỤ LỤC — FAIR, TRIPOD+AI VÀ PROBAST+AI: QUẢN LÝ DỮ LIỆU, BÁO CÁO VÀ THẨM ĐỊNH MÔ HÌNH HỌC MÁY Y TẾ","description":"","frontmatter":{},"headers":[],"relativePath":"phu_luc_fair_tripod_probast.md","filePath":"phu_luc_fair_tripod_probast.md"}'),a={name:"phu_luc_fair_tripod_probast.md"};function o(g,n,r,u,l,d){return h(),i("div",null,[...n[0]||(n[0]=[c('<h1 id="phu-luc-—-fair-tripod-ai-va-probast-ai-quan-ly-du-lieu-bao-cao-va-tham-đinh-mo-hinh-hoc-may-y-te" tabindex="-1">PHỤ LỤC — FAIR, TRIPOD+AI VÀ PROBAST+AI: QUẢN LÝ DỮ LIỆU, BÁO CÁO VÀ THẨM ĐỊNH MÔ HÌNH HỌC MÁY Y TẾ <a class="header-anchor" href="#phu-luc-—-fair-tripod-ai-va-probast-ai-quan-ly-du-lieu-bao-cao-va-tham-đinh-mo-hinh-hoc-may-y-te" aria-label="Permalink to &quot;PHỤ LỤC — FAIR, TRIPOD+AI VÀ PROBAST+AI: QUẢN LÝ DỮ LIỆU, BÁO CÁO VÀ THẨM ĐỊNH MÔ HÌNH HỌC MÁY Y TẾ&quot;">​</a></h1><blockquote><p><strong>Dùng cho:</strong> môn Học máy y tế, bổ trợ Chương 2 (dữ liệu y tế) và Chương 4 (kiểm chứng, đánh giá mô hình). <strong>Nguồn biên soạn:</strong> rút gọn từ bản review nội bộ của đề tài AI-CDSS (suy tim, Alzheimer). Bản review gốc v2.2, ngày 15/10/2026, đã được kiểm chứng nguồn. Toàn bộ tài liệu trích dẫn có trong <code>references/library.bib</code>, metadata đối chiếu Crossref ngày 17/10/2026. <strong>Phần case study</strong> viết theo dạng <strong>gợi ý để sinh viên tự tìm hiểu</strong>: phụ lục nêu câu hỏi và hướng đọc, sinh viên tự đọc bài gốc để trả lời. Số liệu nào không có trong phụ lục thì sinh viên phải lấy từ bài gốc, không suy đoán.</p></blockquote><hr><h2 id="_1-ba-loai-bang-chung-khong-suy-ra-nhau" tabindex="-1">1. Ba loại bằng chứng không suy ra nhau <a class="header-anchor" href="#_1-ba-loai-bang-chung-khong-suy-ra-nhau" aria-label="Permalink to &quot;1. Ba loại bằng chứng không suy ra nhau&quot;">​</a></h2><p>Khi đọc hoặc viết một nghiên cứu học máy y tế, cần tách ba câu hỏi:</p><table tabindex="0"><thead><tr><th>Câu hỏi</th><th>Khung tham chiếu</th><th>Ví dụ câu trả lời sai lầm thường gặp</th></tr></thead><tbody><tr><td>Dữ liệu có được quản lý để tìm thấy, truy cập có kiểm soát, liên thông và tái sử dụng không?</td><td><strong>FAIR</strong> [@wilkinson2016fair; @jacobsen2020fair]</td><td>&quot;Dữ liệu đã công khai trên mạng nên đạt FAIR&quot;</td></tr><tr><td>Nghiên cứu có báo cáo đủ để người khác hiểu và tái lập không?</td><td><strong>TRIPOD+AI</strong> [@collins2024tripodai]</td><td>&quot;Bài có bảng AUC nên đã báo cáo đầy đủ&quot;</td></tr><tr><td>Phương pháp có đáng tin không: nguy cơ sai lệch, tính áp dụng?</td><td><strong>PROBAST+AI</strong> [@moons2025probastai]</td><td>&quot;Báo cáo đầy đủ nên phương pháp đúng&quot;</td></tr></tbody></table><p>Ba loại bằng chứng này độc lập với nhau:</p><ul><li>Dữ liệu đạt FAIR chưa chắc đại diện cho quần thể cần dùng mô hình.</li><li>Báo cáo đầy đủ không có nghĩa là thiết kế đúng.</li><li>AUC cao không chứng minh mô hình có lợi cho bệnh nhân.</li></ul><hr><h2 id="_2-fair-nguyen-tac-quan-ly-du-lieu" tabindex="-1">2. FAIR: nguyên tắc quản lý dữ liệu <a class="header-anchor" href="#_2-fair-nguyen-tac-quan-ly-du-lieu" aria-label="Permalink to &quot;2. FAIR: nguyên tắc quản lý dữ liệu&quot;">​</a></h2><h3 id="_2-1-bon-thanh-phan" tabindex="-1">2.1. Bốn thành phần <a class="header-anchor" href="#_2-1-bon-thanh-phan" aria-label="Permalink to &quot;2.1. Bốn thành phần&quot;">​</a></h3><p>FAIR gồm 15 nguyên tắc con, ký hiệu từ F1 đến R1.3 [@wilkinson2016fair]. Cách diễn giải khi triển khai xem @jacobsen2020fair.</p><table tabindex="0"><thead><tr><th>Thành phần</th><th>Ý nghĩa</th><th>Minh chứng thực hành (gợi ý, không phải nguyên văn FAIR)</th></tr></thead><tbody><tr><td><strong>F</strong>indable</td><td>Có định danh bền vững, metadata phong phú, được lập chỉ mục</td><td>Mã định danh và phiên bản cho dataset; trang mô tả nguồn, thời gian, tiêu chí chọn/loại, cỡ mẫu</td></tr><tr><td><strong>A</strong>ccessible</td><td>Truy cập qua giao thức chuẩn, có xác thực và phân quyền</td><td>Quy trình xin dữ liệu, đầu mối, thỏa thuận sử dụng dữ liệu (DUA). Metadata vẫn truy cập được khi dữ liệu bị hạn chế</td></tr><tr><td><strong>I</strong>nteroperable</td><td>Dùng ngôn ngữ và từ vựng chung</td><td>Từ điển biến, đơn vị; chuẩn trao đổi HL7 FHIR [@hl7_fhir]; mã xét nghiệm LOINC [@loinc_standard]</td></tr><tr><td><strong>R</strong>eusable</td><td>Mô tả đủ để tái sử dụng: nguồn gốc, điều kiện dùng</td><td>Provenance (truy vấn trích xuất, ánh xạ, lịch sử sửa); điều kiện sử dụng; giới hạn</td></tr></tbody></table><h3 id="_2-2-ba-hieu-lam-can-tranh" tabindex="-1">2.2. Ba hiểu lầm cần tránh <a class="header-anchor" href="#_2-2-ba-hieu-lam-can-tranh" aria-label="Permalink to &quot;2.2. Ba hiểu lầm cần tránh&quot;">​</a></h3><ol><li><strong>FAIR không đồng nghĩa với dữ liệu mở.</strong> Dữ liệu bệnh nhân vẫn có thể đạt FAIR mà truy cập bị kiểm soát.</li><li><strong>FAIR không thay thế pháp lý và đạo đức.</strong> Tại Việt Nam, dữ liệu sức khỏe là dữ liệu cá nhân nhạy cảm theo Luật Bảo vệ dữ liệu cá nhân [@luat_bvdlcn_2025] và Nghị định 356/2025/NĐ-CP [@nghi_dinh_356_2025]. Việc nhận được một file dữ liệu không chứng minh đã có phê duyệt đạo đức hay DUA.</li><li><strong>&quot;FAIR&quot; khác &quot;fairness&quot;.</strong> FAIR nói về quản lý dữ liệu. Fairness nói về công bằng của thuật toán giữa các nhóm bệnh nhân. Đây là hai khái niệm khác nhau.</li></ol><h3 id="_2-3-tai-lieu-hoa" tabindex="-1">2.3. Tài liệu hóa <a class="header-anchor" href="#_2-3-tai-lieu-hoa" aria-label="Permalink to &quot;2.3. Tài liệu hóa&quot;">​</a></h3><p>Mỗi dataset nên có một <strong>datasheet</strong> [@gebru2021datasheets] mô tả: động cơ thu thập, thành phần, quy trình thu thập và tiền xử lý, mục đích khuyến nghị, giới hạn. Trong đồ án môn học, datasheet là phần bắt buộc của hồ sơ dữ liệu (mục 7).</p><hr><h2 id="_3-tripod-ai-bao-cao-minh-bach-mo-hinh-du-đoan" tabindex="-1">3. TRIPOD+AI: báo cáo minh bạch mô hình dự đoán <a class="header-anchor" href="#_3-tripod-ai-bao-cao-minh-bach-mo-hinh-du-đoan" aria-label="Permalink to &quot;3. TRIPOD+AI: báo cáo minh bạch mô hình dự đoán&quot;">​</a></h2><h3 id="_3-1-pham-vi" tabindex="-1">3.1. Phạm vi <a class="header-anchor" href="#_3-1-pham-vi" aria-label="Permalink to &quot;3.1. Phạm vi&quot;">​</a></h3><p>TRIPOD+AI [@collins2024tripodai] là hướng dẫn báo cáo cho nghiên cứu <strong>phát triển hoặc đánh giá mô hình dự đoán lâm sàng</strong>, áp dụng cho cả hồi quy lẫn học máy. Hướng dẫn gồm 27 mục và một checklist riêng cho phần tóm tắt. Bản checklist chính thức có trên trang của TRIPOD; sinh viên tự tải về để dùng.</p><h3 id="_3-2-chon-huong-dan-theo-cau-hoi-nghien-cuu-khong-theo-dang-đau-ra" tabindex="-1">3.2. Chọn hướng dẫn theo câu hỏi nghiên cứu, không theo dạng đầu ra <a class="header-anchor" href="#_3-2-chon-huong-dan-theo-cau-hoi-nghien-cuu-khong-theo-dang-đau-ra" aria-label="Permalink to &quot;3.2. Chọn hướng dẫn theo câu hỏi nghiên cứu, không theo dạng đầu ra&quot;">​</a></h3><p>Mô hình xuất ra xác suất không có nghĩa là luôn dùng TRIPOD+AI. Chọn theo <strong>câu hỏi và thiết kế</strong> nghiên cứu:</p><table tabindex="0"><thead><tr><th>Câu hỏi nghiên cứu</th><th>Hướng dẫn báo cáo</th></tr></thead><tbody><tr><td>Phát triển hoặc kiểm định mô hình dự đoán chẩn đoán/tiên lượng</td><td>TRIPOD+AI [@collins2024tripodai]</td></tr><tr><td>Độ chính xác của một xét nghiệm dựa trên AI so với chuẩn tham chiếu</td><td>STARD-AI [@sounderajah2025stardai]</td></tr><tr><td>Đánh giá lâm sàng giai đoạn sớm của hệ hỗ trợ quyết định dùng AI</td><td>DECIDE-AI [@vasey2022decideai]</td></tr></tbody></table><hr><h2 id="_4-probast-ai-tham-đinh-nguy-co-sai-lech-va-tinh-ap-dung" tabindex="-1">4. PROBAST+AI: thẩm định nguy cơ sai lệch và tính áp dụng <a class="header-anchor" href="#_4-probast-ai-tham-đinh-nguy-co-sai-lech-va-tinh-ap-dung" aria-label="Permalink to &quot;4. PROBAST+AI: thẩm định nguy cơ sai lệch và tính áp dụng&quot;">​</a></h2><p>PROBAST+AI [@moons2025probastai] đánh giá hai phần <strong>tách biệt</strong>:</p><ul><li><strong>Phát triển mô hình:</strong> chất lượng của quá trình xây dựng mô hình.</li><li><strong>Đánh giá mô hình:</strong> nguy cơ sai lệch của phép đánh giá hiệu năng và tính áp dụng cho quần thể đích.</li></ul><p>Bản gốc có bảng các câu hỏi báo hiệu (signalling questions), chia theo bốn miền: người tham gia và nguồn dữ liệu, biến dự báo, kết cục, phân tích. Sinh viên đọc bảng này trong bài gốc trước khi làm bài tập ở mục 8.</p><p><strong>Vì sao cần thẩm định?</strong> Một tổng quan hệ thống về 152 nghiên cứu mô hình học máy có giám sát cho thấy <strong>87%</strong> lượt đánh giá có nguy cơ sai lệch cao. Lỗi hay gặp là cỡ mẫu không đủ so với số biến, xử lý dữ liệu thiếu không phù hợp, và đánh giá overfitting không đúng [@andaurnavarro2021rob].</p><p><strong>Lỗi phương pháp sinh viên hay mắc (đối chiếu với PROBAST+AI):</strong></p><ol><li><strong>Rò rỉ dữ liệu (leakage):</strong> chuẩn hóa, imputation hay chọn biến trên toàn bộ dữ liệu trước khi chia train/test. Tất cả các bước này phải fit <strong>chỉ trên tập huấn luyện</strong>.</li><li><strong>Chia theo dòng thay vì theo bệnh nhân:</strong> một bệnh nhân có nhiều lần khám rơi vào cả tập train lẫn test.</li><li><strong>Dùng thông tin tương lai:</strong> dùng biến chỉ có sau thời điểm ra quyết định (T0) làm đầu vào.</li><li><strong>Thiên lệch do đưa biến dự báo vào nhãn (incorporation bias):</strong> nhãn được tạo từ chính một biến đầu vào. Ví dụ: gán nhãn suy tim bằng ngưỡng NT-proBNP rồi lại dùng NT-proBNP để dự đoán nhãn đó. Hiệu năng khi đó bị thổi phồng.</li><li><strong>Coi độ đầy đủ dữ liệu là độ đúng của nhãn:</strong> hồ sơ đầy đủ biến vẫn có thể bị gán nhãn sai. Chất lượng nhãn phải được đánh giá riêng.</li></ol><hr><h2 id="_5-đanh-gia-hieu-nang-khong-chi-co-auc" tabindex="-1">5. Đánh giá hiệu năng: không chỉ có AUC <a class="header-anchor" href="#_5-đanh-gia-hieu-nang-khong-chi-co-auc" aria-label="Permalink to &quot;5. Đánh giá hiệu năng: không chỉ có AUC&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Khía cạnh</th><th>Chỉ số</th><th>Lưu ý</th></tr></thead><tbody><tr><td>Phân biệt (discrimination)</td><td>AUC/C-statistic</td><td>Không cho biết xác suất dự đoán có đúng mức hay không</td></tr><tr><td>Chuẩn định (calibration)</td><td>Đường cong calibration; <strong>calibration-in-the-large</strong> (intercept khi slope cố định bằng 1); <strong>calibration slope</strong></td><td>Calibration là &quot;gót chân Achilles&quot; của mô hình dự đoán [@vancalster2019calibration]. Slope &lt; 1 thường là dấu hiệu overfitting</td></tr><tr><td>Hiệu năng tổng thể</td><td>Brier score</td><td>Brier phản ánh đồng thời phân biệt, calibration và tỷ lệ kết cục. <strong>Không</strong> dùng Brier đơn độc để kết luận mô hình được chuẩn định tốt</td></tr><tr><td>Lợi ích lâm sàng</td><td>Decision curve analysis (net benefit)</td><td>Cho biết dùng mô hình ở một ngưỡng có lợi hơn chiến lược &quot;điều trị tất cả&quot; hay &quot;không điều trị ai&quot; không</td></tr></tbody></table><p><strong>Cỡ mẫu là nhiều bài toán khác nhau,</strong> không có một con số chung:</p><ul><li>Phát triển mô hình: tính theo số tham số, tỷ lệ kết cục và mức overfitting cho phép [@riley2020samplesize].</li><li>Kiểm định ngoài: tính theo độ chính xác mong muốn của các chỉ số hiệu năng [@riley2024external].</li><li>Độ chính xác tại ngưỡng và nghiên cứu can thiệp: cần phép tính riêng.</li></ul><hr><h2 id="_6-case-study-goi-y-đe-sinh-vien-tu-tim-hieu" tabindex="-1">6. Case study: gợi ý để sinh viên tự tìm hiểu <a class="header-anchor" href="#_6-case-study-goi-y-đe-sinh-vien-tu-tim-hieu" aria-label="Permalink to &quot;6. Case study: gợi ý để sinh viên tự tìm hiểu&quot;">​</a></h2><p>Mỗi case study có <strong>câu chuyện ngắn</strong>, <strong>bài cần đọc</strong> và <strong>câu hỏi</strong>. Sinh viên trả lời bằng bằng chứng trích từ bài gốc: ghi số trang, bảng, hình.</p><h3 id="_6-1-suy-tim" tabindex="-1">6.1. Suy tim <a class="header-anchor" href="#_6-1-suy-tim" aria-label="Permalink to &quot;6.1. Suy tim&quot;">​</a></h3><p><strong>Case HF-1. Bộ dữ liệu sống còn suy tim (UCI) và &quot;chỉ cần hai biến&quot;</strong></p><ul><li><strong>Đọc:</strong> @chicco2020machine. Bài kết luận rằng creatinin huyết thanh và phân suất tống máu (EF) có thể dự đoán sống còn.</li><li><strong>Câu hỏi:</strong><ol><li>Dataset có bao nhiêu bệnh nhân, thu thập ở đâu, khi nào? Quần thể đó có giống bệnh nhân suy tim ≥ 60 tuổi ở Việt Nam không? (tính áp dụng, PROBAST+AI)</li><li>Biến <code>time</code> (thời gian theo dõi) có nên dùng làm đầu vào không? Vì sao đây có thể là rò rỉ thông tin tương lai?</li><li>Lập datasheet [@gebru2021datasheets] cho dataset này. Mục nào <strong>không</strong> có thông tin?</li><li>Tự huấn luyện hồi quy logistic và một mô hình cây. Báo cáo AUC, đường cong calibration, Brier. Kết luận &quot;hai biến là đủ&quot; có còn đứng vững không?</li></ol></li></ul><p><strong>Case HF-2. AI-ECG: từ AUC cao đến tác động thực tế</strong></p><ul><li><strong>Đọc:</strong> @attia2019aiecg (phát triển và kiểm định AI đọc điện tâm đồ để phát hiện rối loạn chức năng thất trái) và @yao2021eagle (thử nghiệm thực địa EAGLE).</li><li><strong>Gợi ý:</strong> AUC đo khả năng phân biệt. EAGLE đo thay đổi tỷ lệ chẩn đoán khi bác sĩ được dùng công cụ, với mức tăng tuyệt đối khoảng 0,5 điểm phần trăm [@yao2021eagle]. Hai chỉ số trả lời hai câu hỏi khác nhau, <strong>không so sánh trực tiếp độ lớn</strong>.</li><li><strong>Câu hỏi:</strong><ol><li>Ngưỡng EF dùng để định nghĩa nhãn ở hai nghiên cứu có giống nhau không? Có được ghép số liệu của hai bài không?</li><li>Thiết kế EAGLE thuộc loại gì? Hướng dẫn báo cáo nào phù hợp (mục 3.2)?</li><li>Vì sao một mô hình có AUC cao vẫn có thể tạo tác động lâm sàng nhỏ?</li></ol></li></ul><p><strong>Case HF-3. CoDE-HF: chẩn đoán suy tim cấp dựa trên NT-proBNP</strong></p><ul><li><strong>Đọc:</strong> @lee2022codehf (phát triển và kiểm định) và @doudesis2026codehf (kiểm định tiến cứu, <strong>chỉ là abstract hội nghị một trang</strong>).</li><li><strong>Câu hỏi:</strong><ol><li>Mô hình cần những biến nào <strong>tại thời điểm dự đoán</strong>? Nếu bệnh viện chưa có NT-proBNP lúc khám ban đầu thì có dùng được mô hình không?</li><li>Chuẩn tham chiếu (nhãn suy tim cấp) được xác lập thế nào? Có nguy cơ incorporation bias không?</li><li>Dùng TRIPOD+AI cho phần tóm tắt để đánh giá abstract 2026. Mục nào <strong>không đủ thông tin</strong>? Vì sao không được lấy chi tiết của bài 2022 để lấp chỗ trống cho nghiên cứu 2026?</li><li>Thử thẩm định abstract 2026 bằng phần &quot;đánh giá mô hình&quot; của PROBAST+AI. Kết luận có thể là &quot;không rõ&quot; (unclear) không, và vì sao?</li></ol></li></ul><h3 id="_6-2-tieu-đuong" tabindex="-1">6.2. Tiểu đường <a class="header-anchor" href="#_6-2-tieu-đuong" aria-label="Permalink to &quot;6.2. Tiểu đường&quot;">​</a></h3><p><strong>Case DM-1. Bệnh võng mạc đái tháo đường: từ phòng thí nghiệm đến phòng khám</strong></p><ul><li><strong>Đọc:</strong> theo thứ tự @gulshan2016dr (phát triển và kiểm định deep learning trên ảnh đáy mắt), @abramoff2018autonomous (thử nghiệm then chốt của hệ thống AI chẩn đoán tự động), @beede2020humancentered (đánh giá lấy con người làm trung tâm khi triển khai tại phòng khám).</li><li><strong>Câu hỏi:</strong><ol><li>Ba bài lần lượt trả lời ba câu hỏi gì? Hướng dẫn báo cáo nào phù hợp cho từng bài (STARD-AI, TRIPOD+AI, DECIDE-AI)?</li><li>Theo @beede2020humancentered, những yếu tố nào ngoài mô hình (chất lượng ảnh, quy trình, hạ tầng) làm hiệu quả thực tế khác với kết quả trong phòng thí nghiệm?</li><li>Chuẩn tham chiếu (người chấm ảnh) ở mỗi nghiên cứu là ai? Điều đó ảnh hưởng đến cách hiểu độ nhạy và độ đặc hiệu ra sao?</li></ol></li></ul><p><strong>Case DM-2. Tái nhập viện ở bệnh nhân đái tháo đường: bộ dữ liệu 130 bệnh viện Hoa Kỳ</strong></p><ul><li><strong>Đọc:</strong> @strack2014hba1c. Bài phân tích khoảng 70.000 hồ sơ để xem việc đo HbA1c có liên quan đến tái nhập viện không. Đây là nguồn gốc của bộ dữ liệu &quot;Diabetes 130-US hospitals&quot; thường gặp trên UCI.</li><li><strong>Câu hỏi:</strong><ol><li>Đơn vị của mỗi dòng là bệnh nhân hay lượt nhập viện? Nếu chia train/test theo dòng thì có rò rỉ không, và nên chia thế nào?</li><li>HbA1c bị thiếu ở phần lớn hồ sơ. &quot;Không đo HbA1c&quot; là dữ liệu thiếu hay là một thông tin lâm sàng? Chọn cách xử lý nào và giải thích theo PROBAST+AI.</li><li>Các mã chẩn đoán ICD-9 trong dataset cần ánh xạ gì để liên thông với dữ liệu Việt Nam (ICD-10)? Đây là nguyên tắc FAIR nào?</li></ol></li></ul><p><strong>Case DM-3. Mô hình nguy cơ đái tháo đường týp 2 trong cộng đồng: QDiabetes-2018</strong></p><ul><li><strong>Đọc:</strong> @hippisleycox2017qdiabetes. Có thể đọc thêm tổng quan @kavakiotis2017diabetes để thấy bức tranh rộng của học máy trong nghiên cứu đái tháo đường.</li><li><strong>Câu hỏi:</strong><ol><li>Mô hình báo cáo những khía cạnh nào trong mục 5: phân biệt, calibration, hay cả hai? Theo bạn còn thiếu gì?</li><li>Nếu muốn dùng QDiabetes cho người Việt Nam thì cần <strong>kiểm định ngoài</strong>. Cỡ mẫu tính theo @riley2024external cần những thông tin đầu vào nào?</li><li>So sánh cách tiếp cận &quot;mô hình hồi quy kinh điển trên dữ liệu lớn&quot; (QDiabetes) với các mô hình học máy trong tổng quan @kavakiotis2017diabetes. Cái nào dễ kiểm định và giải thích hơn?</li></ol></li></ul><p><strong>Tự tra cứu thêm (không có trong thư viện tham khảo):</strong> bộ dữ liệu &quot;Pima Indians Diabetes&quot; thường được dùng trong bài tập. Sinh viên tự tìm nguồn gốc của dataset, quần thể thu thập và các vấn đề như giá trị 0 thay cho dữ liệu thiếu. Sau đó đánh giá dataset theo mục 2 và mục 4 của phụ lục này.</p><hr><h2 id="_7-bang-kiem-nhanh-cho-đo-an-mon-hoc" tabindex="-1">7. Bảng kiểm nhanh cho đồ án môn học <a class="header-anchor" href="#_7-bang-kiem-nhanh-cho-đo-an-mon-hoc" aria-label="Permalink to &quot;7. Bảng kiểm nhanh cho đồ án môn học&quot;">​</a></h2><p><strong>Dữ liệu (FAIR)</strong></p><ul><li>[ ] Datasheet: nguồn, thời gian, quần thể, tiêu chí chọn/loại, định nghĩa và đơn vị biến, giới hạn.</li><li>[ ] Phiên bản và checksum của file dữ liệu dùng để huấn luyện.</li><li>[ ] Không có định danh bệnh nhân. Nêu căn cứ được phép dùng dữ liệu (dữ liệu công khai, giấy phép, DUA).</li></ul><p><strong>Báo cáo (TRIPOD+AI)</strong></p><ul><li>[ ] Đã chọn đúng hướng dẫn theo câu hỏi nghiên cứu (mục 3.2) và đính kèm checklist đã điền.</li><li>[ ] Định nghĩa rõ kết cục, nhãn, thời điểm dự đoán T0 và các biến có sẵn tại T0.</li></ul><p><strong>Phương pháp (PROBAST+AI)</strong></p><ul><li>[ ] Chia dữ liệu theo bệnh nhân. Mọi bước tiền xử lý fit chỉ trên tập huấn luyện.</li><li>[ ] Có mô hình mốc là hồi quy logistic.</li><li>[ ] Báo cáo AUC, đường cong calibration, calibration-in-the-large, slope, Brier, kèm khoảng tin cậy 95%.</li><li>[ ] Nêu rõ cỡ mẫu có đủ không, và giới hạn về tính áp dụng.</li></ul><hr><h2 id="_8-bai-tap-goi-y" tabindex="-1">8. Bài tập gợi ý <a class="header-anchor" href="#_8-bai-tap-goi-y" aria-label="Permalink to &quot;8. Bài tập gợi ý&quot;">​</a></h2><ol><li><strong>Thẩm định một bài báo:</strong> chọn một bài học máy y tế về suy tim hoặc tiểu đường. Đánh giá phần báo cáo theo TRIPOD+AI và phần phương pháp theo PROBAST+AI. Trình bày dạng bảng: mã mục, vị trí bằng chứng trong bài, nhận định, lý do.</li><li><strong>Sửa một notebook bị rò rỉ:</strong> giảng viên cung cấp notebook có lỗi leakage (chuẩn hóa trước khi chia, chia theo dòng). Sinh viên tìm lỗi, sửa và so sánh AUC trước và sau khi sửa.</li><li><strong>Datasheet và FAIR:</strong> viết datasheet cho một dataset công khai (UCI suy tim hoặc Diabetes 130-US). Chỉ ra nguyên tắc FAIR nào chưa đạt và cần bổ sung gì.</li></ol><hr><h2 id="_9-loi-giai-tham-khao-ket-qua-review-mau-tu-mot-du-an-thuc" tabindex="-1">9. Lời giải tham khảo: kết quả review mẫu từ một dự án thực <a class="header-anchor" href="#_9-loi-giai-tham-khao-ket-qua-review-mau-tu-mot-du-an-thuc" aria-label="Permalink to &quot;9. Lời giải tham khảo: kết quả review mẫu từ một dự án thực&quot;">​</a></h2><blockquote><p>Dành cho giảng viên, hoặc để sinh viên đối chiếu <strong>sau khi</strong> đã tự làm case HF-3 và bài tập 1. Nội dung rút từ bản review nội bộ của một đề tài AI-CDSS suy tim tại bệnh viện (v2.2, 15/10/2026). Cách trình bày theo đúng mẫu mà sinh viên cần nộp: mỗi nhận định có mã mục, vị trí bằng chứng và lý do.</p></blockquote><h3 id="_9-1-code-hf-2026-tham-đinh-mot-abstract-hoi-nghi" tabindex="-1">9.1. CoDE-HF 2026: thẩm định một abstract hội nghị <a class="header-anchor" href="#_9-1-code-hf-2026-tham-đinh-mot-abstract-hoi-nghi" aria-label="Permalink to &quot;9.1. CoDE-HF 2026: thẩm định một abstract hội nghị&quot;">​</a></h3><p><strong>Bước 1. Nhận diện loại bằng chứng.</strong> @doudesis2026codehf là <strong>abstract hội nghị một trang</strong>, không phải toàn văn. Vì vậy:</p><ul><li>phần báo cáo được đánh giá bằng <strong>TRIPOD+AI for Abstracts</strong> (13 mục);</li><li>PROBAST+AI chỉ dùng <strong>phần đánh giá mô hình</strong> (18 câu hỏi) để kết luận sơ bộ;</li><li>bài phát triển năm 2022 [@lee2022codehf] chỉ là bối cảnh, <strong>không dùng để lấp chỗ thiếu</strong> của nghiên cứu 2026.</li></ul><p><strong>Bước 2. Đọc đúng số liệu.</strong> Abstract báo cáo cohort 1.030 người, trong đó 374 ca suy tim cấp (AHF) đã được thẩm định. Cần đọc kỹ: AUC 0,839 (KTC 95% 0,809–0,869) và Brier 0,152 <strong>chỉ thuộc nhóm không có tiền sử suy tim</strong>, không phải toàn cohort. Ở nhóm này, CoDE-HF xếp 30% ca vào nhóm nguy cơ thấp và 19% vào nhóm nguy cơ cao, nên khoảng 51% còn ở <strong>vùng trung gian</strong>, cần có đường xử trí riêng. Brier là chỉ số hiệu năng tổng thể: con số 0,152 <strong>không đủ</strong> để kết luận calibration tốt (mục 5).</p><p><strong>Bước 3. TRIPOD+AI for Abstracts.</strong></p><table tabindex="0"><thead><tr><th>Mức</th><th>Các mục</th><th>Ghi chú</th></tr></thead><tbody><tr><td>Có</td><td>2 (bối cảnh), 3 (mục tiêu), 8 (chỉ số hiệu năng), 9 (số người tham gia, số kết cục — ở toàn cohort), 10 (biến dự báo, liệt kê đủ 10 biến)</td><td>Mục 8 chỉ hỏi chỉ số nào được dùng; việc thiếu calibration được xử lý ở PROBAST+AI</td></tr><tr><td>Một phần</td><td>1 (tiêu đề chưa nêu quần thể), 4 (nguồn dữ liệu chưa nêu trung tâm, thời gian), 5 (chưa nêu tuyển liên tiếp, tiêu chí loại), 6 (chưa nêu tiêu chuẩn chẩn đoán AHF), 11 (Brier không có KTC)</td><td></td></tr><tr><td>Cần giới hạn</td><td>12 (kết luận &quot;hỗ trợ quyết định&quot; trong khi chưa có nghiên cứu tác động)</td><td></td></tr><tr><td>Không áp dụng</td><td>7 (cách xây dựng mô hình, vì đây là nghiên cứu đánh giá)</td><td></td></tr><tr><td>Không thấy</td><td>13 (số đăng ký)</td><td>Không được suy ra là nghiên cứu không đăng ký</td></tr></tbody></table><p>Bảng này <strong>không</strong> quy thành &quot;tỷ lệ tuân thủ&quot;: số mục áp dụng thay đổi theo thiết kế, và chưa có quy tắc chấm &quot;Một phần&quot; định trước.</p><p><strong>Bước 4. PROBAST+AI, phần đánh giá mô hình.</strong> Mã trả lời: Y, PY, PN, N, NI (không đủ thông tin), NA.</p><table tabindex="0"><thead><tr><th>Miền</th><th>Nhận định chính</th><th>Kết luận miền</th></tr></thead><tbody><tr><td>1. Người tham gia, nguồn dữ liệu</td><td>Cohort tiến cứu, thiết kế kiểm định ngoài phù hợp (PY); không rõ tuyển liên tiếp và số ca bị loại (NI)</td><td>Chưa rõ</td></tr><tr><td>2. Biến dự báo</td><td>Không nêu assay, đơn vị, cách tính eGFR, thời điểm biến có sẵn (NI)</td><td>Chưa rõ</td></tr><tr><td>3. Kết cục</td><td>Có hội đồng thẩm định (điểm tốt), nhưng &quot;hai bác sĩ độc lập&quot; chưa chứng minh được làm mù với NT-proBNP (NI)</td><td>Chưa rõ</td></tr><tr><td>4. Phân tích</td><td>Có discrimination và độ chính xác tại ngưỡng; không có đường cong calibration, không có net benefit, không có lý giải cỡ mẫu (NI). Câu về chia train/test là NA có điều kiện, vì đây là kiểm định ngoài</td><td>Chưa rõ</td></tr></tbody></table><p><strong>Kết luận:</strong> nguy cơ sai lệch tổng thể là <strong>unclear do thiếu thông tin</strong>, không phải &quot;cao&quot; hay &quot;thấp&quot;. Đây là kết luận đúng đắn với một abstract: thiếu thông tin thì ghi thiếu thông tin, không đoán.</p><p><strong>Bước 5. FAIR của nghiên cứu.</strong> Bài báo có DOI nên <strong>bài báo</strong> tìm thấy được. Abstract không có định danh dataset, từ điển dữ liệu, điều kiện truy cập dữ liệu hay mã nguồn/phiên bản mô hình. Vì vậy chưa đủ minh chứng để kết luận dataset đạt FAIR. Không có minh chứng cũng không có nghĩa là các hồ sơ đó không tồn tại.</p><p><strong>Bước 6. Hồ sơ cần có để hoàn tất thẩm định:</strong></p><ul><li>protocol hoặc SAP, số đăng ký;</li><li>sơ đồ sàng lọc và loại ca;</li><li>phiên bản mô hình, ngưỡng đã khóa;</li><li>tiêu chuẩn chẩn đoán AHF và cách làm mù;</li><li>tỷ lệ dữ liệu thiếu; assay và đơn vị;</li><li>confusion matrix tại từng ngưỡng; calibration kèm KTC;</li><li>phê duyệt đạo đức và điều kiện truy cập dữ liệu.</li></ul><h3 id="_9-2-audit-fair-mot-ban-xuat-du-lieu-benh-vien-va-co-kiem-đinh-đuoc-code-hf-khong" tabindex="-1">9.2. Audit FAIR một bản xuất dữ liệu bệnh viện, và có kiểm định được CoDE-HF không? <a class="header-anchor" href="#_9-2-audit-fair-mot-ban-xuat-du-lieu-benh-vien-va-co-kiem-đinh-đuoc-code-hf-khong" aria-label="Permalink to &quot;9.2. Audit FAIR một bản xuất dữ liệu bệnh viện, và có kiểm định được CoDE-HF không?&quot;">​</a></h3><p><strong>Dữ liệu:</strong> bản xuất xét nghiệm dạng rộng của một bệnh viện, đã giả danh, không công khai: 330 dòng, 13 cột. Có mã bệnh nhân giả, giới, năm sinh và 10 cột xét nghiệm. Không có chẩn đoán, thời điểm lấy mẫu hay đơn vị.</p><p><strong>FAIR, nhận định theo minh chứng có trong gói dữ liệu:</strong></p><table tabindex="0"><thead><tr><th>Nguyên tắc</th><th>Hiện có</th><th>Cần bổ sung</th></tr></thead><tbody><tr><td>F (tìm thấy)</td><td>Chỉ có tên file</td><td>Định danh và phiên bản dataset, datasheet [@gebru2021datasheets], metadata kèm checksum</td></tr><tr><td>A (truy cập)</td><td>Đã nhận được file, chưa có cơ chế được mô tả</td><td>Quy trình truy cập, phân quyền, DUA</td></tr><tr><td>I (liên thông)</td><td>CSV máy đọc được, nhưng chỉ có tên cột cục bộ</td><td>Đơn vị; mã LOINC [@loinc_standard]; khóa liên kết bệnh nhân – lượt khám – mẫu – thời điểm</td></tr><tr><td>R (tái sử dụng)</td><td>Thiếu định nghĩa biến, nguồn gốc</td><td>Provenance (truy vấn trích xuất, ánh xạ, lịch sử sửa), điều kiện sử dụng</td></tr></tbody></table><p><strong>Kết luận:</strong> máy đọc được, nhưng <strong>chưa đủ minh chứng</strong> về khả năng tìm thấy, truy cập có điều kiện và tái sử dụng. Không gán nhãn &quot;đạt/không đạt FAIR&quot; bằng một tổng điểm tự đặt.</p><p><strong>Gap analysis để kiểm định CoDE-HF.</strong> CoDE-HF cần 10 biến dự báo, cộng thêm biến tiền sử suy tim để chọn nhánh và nhãn AHF tham chiếu:</p><table tabindex="0"><thead><tr><th>Mức sẵn sàng</th><th>Biến</th></tr></thead><tbody><tr><td>Có trực tiếp (1/10)</td><td>NT-proBNP. Vẫn cần đơn vị, assay, thời điểm, và xác minh giá trị trùng mức tối đa của máy</td></tr><tr><td>Dựng được có điều kiện (2/10)</td><td>Tuổi tại thời điểm đánh giá (cần ngày lấy mẫu); eGFR (cần creatinin hợp lệ, đơn vị, công thức được duyệt)</td></tr><tr><td>Thiếu (7/10)</td><td>Hemoglobin, BMI, nhịp tim, huyết áp tâm thu, phù ngoại vi, COPD, bệnh tim thiếu máu cục bộ</td></tr><tr><td>Thiếu, chặn đánh giá</td><td>Tiền sử suy tim (không chọn được nhánh); nhãn AHF tham chiếu</td></tr></tbody></table><p><strong>Những suy luận phải tránh:</strong></p><ul><li>Không dùng <code>NT_proBNP ≥ 300</code> làm nhãn rồi báo cáo AUC của một mô hình có NT-proBNP. Đó là vòng lặp, không đánh giá được chẩn đoán độc lập (incorporation bias, mục 4).</li><li>Không gán bệnh sử bị thiếu thành &quot;không có bệnh&quot;, và không coi ca thiếu nhãn là âm tính.</li><li>Không kết luận đủ hay thiếu cỡ mẫu từ một bản xuất chưa có nhãn.</li><li>Không tự chia 10 hay 100 các giá trị nghi sai đơn vị. Phải truy hồi về nguồn xét nghiệm.</li></ul><h3 id="_9-3-bai-hoc-thiet-ke-rut-ra-tu-review-du-an" tabindex="-1">9.3. Bài học thiết kế rút ra từ review dự án <a class="header-anchor" href="#_9-3-bai-hoc-thiet-ke-rut-ra-tu-review-du-an" aria-label="Permalink to &quot;9.3. Bài học thiết kế rút ra từ review dự án&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Vấn đề phát hiện khi review</th><th>Cách viết đúng</th></tr></thead><tbody><tr><td>Đề cương ghi &quot;hồ sơ đủ biến (Tier A) là ground truth&quot;</td><td>Tách ba trục độc lập: độ đầy đủ đầu vào; chất lượng nhãn/chuẩn tham chiếu; khả năng có biến tại T0</td></tr><tr><td>Chọn TRIPOD+AI &quot;vì đầu ra là xác suất&quot;</td><td>Chọn theo câu hỏi nghiên cứu: TRIPOD+AI / STARD-AI / DECIDE-AI (mục 3.2)</td></tr><tr><td>Một mốc cỡ mẫu chung cho mọi giai đoạn</td><td>Tính riêng cho phát triển [@riley2020samplesize], kiểm định ngoài [@riley2024external], độ chính xác tại ngưỡng, và can thiệp</td></tr><tr><td>&quot;Brier tốt nên calibration tốt&quot;</td><td>Brier là hiệu năng tổng thể. Phải báo cáo đường cong, calibration-in-the-large và slope [@vancalster2019calibration]</td></tr><tr><td>So sánh độ lớn AUC với mức tăng tỷ lệ chẩn đoán trong thử nghiệm</td><td>Hai chỉ số trả lời hai câu hỏi khác nhau [@yao2021eagle]</td></tr><tr><td>Tập Test chỉ gồm ca đủ dữ liệu</td><td>Tập đánh giá phải phản ánh luồng ca thực tế tại T0. Nếu hệ thống từ chối dự đoán khi thiếu biến, phải báo cáo tỷ lệ bị từ chối</td></tr><tr><td>Luật an toàn thuốc &quot;không thuộc phạm vi hướng dẫn&quot;</td><td>Không dùng PROBAST+AI để chấm luật, nhưng báo cáo can thiệp vẫn phải mô tả nguồn luật, phiên bản, lỗi đã biết và hành vi ghi đè của bác sĩ</td></tr></tbody></table><hr><h2 id="tai-lieu-tham-khao" tabindex="-1">Tài liệu tham khảo <a class="header-anchor" href="#tai-lieu-tham-khao" aria-label="Permalink to &quot;Tài liệu tham khảo&quot;">​</a></h2><p>Toàn bộ khóa trích dẫn ở trên có trong <code>references/library.bib</code>. Trong đó 21 mục mới được thêm ngày 17/10/2026, metadata đối chiếu Crossref theo DOI.</p>',96)])])}const m=t(a,[["render",o]]);export{e as __pageData,m as default};
